void setup() {
  // Инициализируем пин 13 как выход
  pinMode(13, OUTPUT);
}

void loop() {
  // Включаем светодиод (подаём HIGH на пин)
  digitalWrite(13, HIGH);
  // Задержка на 1 секунду (1000 мс)
  delay(1000);

  // Выключаем светодиод (снимаем напряжение с пина)
  digitalWrite(13, LOW);
  // Задержка на 1 секунду (1000 мс)
  delay(1000);
}
